// C documentation
//
//	/*
//	 - stid - identify a subtree node for dumping
//	 ^ static const char *stid(struct subre *, char *, size_t);
//	 */
func _stid(tls *libc.TLS, t uintptr, buf uintptr, bufsize Tsize_t) (r uintptr) {
	bp := tls.Alloc(16)
	defer tls.Free(16)
	/*
	 * Big enough for hex int or decimal t->id?
	 */
	if bufsize < libc.Uint64FromInt64(8)*libc.Uint64FromInt32(2)+libc.Uint64FromInt32(3) || bufsize < libc.Uint64FromInt64(2)*libc.Uint64FromInt32(3)+libc.Uint64FromInt32(1) {
		return __ccgo_ts + 11030
	}
	if int32((*Tsubre)(unsafe.Pointer(t)).Fid) != 0 {
		libc.Xsprintf(tls, buf, __ccgo_ts+5612, libc.VaList(bp+8, int32((*Tsubre)(unsafe.Pointer(t)).Fid)))
	} else {
		libc.Xsprintf(tls, buf, __ccgo_ts+1655, libc.VaList(bp+8, t))
	}
	return buf
}

