// C documentation
//
//	/*
//	 - lexstart - set up lexical stuff, scan leading options
//	 ^ static void lexstart(struct vars *);
//	 */
func _lexstart(tls *libc.TLS, v uintptr) {
	_prefixes(tls, v) /* may turn on new type bits etc. */
	if (*Tvars)(unsafe.Pointer(v)).Ferr != 0 {
		return
	}
	if (*Tvars)(unsafe.Pointer(v)).Fcflags&int32(m_REG_QUOTE) != 0 {
		(*Tvars)(unsafe.Pointer(v)).Flexcon = int32(m_L_Q)
	} else {
		if (*Tvars)(unsafe.Pointer(v)).Fcflags&int32(m_REG_EXTENDED) != 0 {
			(*Tvars)(unsafe.Pointer(v)).Flexcon = int32(m_L_ERE)
		} else {
			(*Tvars)(unsafe.Pointer(v)).Flexcon = int32(m_L_BRE)
		}
	}
	(*Tvars)(unsafe.Pointer(v)).Fnexttype = int32('n') /* remember we were at the start */
	_next(tls, v)                                      /* set up the first token */
}

