/*
 * Source instruction type recognized by the assembler.
 */

type TTalInstType = int32

/*
 * Source instruction type recognized by the assembler.
 */

type _TalInstType = int32

const _ASSEM_1BYTE = 0
const /* Fixed arity, 1-byte instruction */
_ASSEM_BEGIN_CATCH = 1
const /* Begin catch: one 4-byte jump offset to be
 * converted to appropriate exception
 * ranges */
_ASSEM_BOOL = 2
const /* One Boolean operand */
_ASSEM_BOOL_LVT4 = 3
const /* One Boolean, one 4-byte LVT ref. */
_ASSEM_CLOCK_READ = 4
const /* 1-byte unsigned-integer case number, in the
 * range 0-3 */
_ASSEM_CONCAT1 = 5
const /* 1-byte unsigned-integer operand count, must
 * be strictly positive, consumes N, produces
 * 1 */
_ASSEM_DICT_GET = 6
const /* 'dict get' and related - consumes N+1
 * operands, produces 1, N > 0 */
_ASSEM_DICT_SET = 7
const /* specifies key count and LVT index, consumes
 * N+1 operands, produces 1, N > 0 */
_ASSEM_DICT_UNSET = 8
const /* specifies key count and LVT index, consumes
 * N operands, produces 1, N > 0 */
_ASSEM_END_CATCH = 9
const /* End catch. No args. Exception range popped
 * from stack and stack pointer restored. */
_ASSEM_EVAL = 10
const /* 'eval' - evaluate a constant script (by
 * compiling it in line with the assembly
 * code! I love Tcl!) */
_ASSEM_INDEX = 11
const /* 4 byte operand, integer or end-integer */
_ASSEM_INVOKE = 12
const /* 1- or 4-byte operand count, must be
 * strictly positive, consumes N, produces
 * 1. */
_ASSEM_JUMP = 13
const /* Jump instructions */
_ASSEM_JUMP4 = 14
const /* Jump instructions forcing a 4-byte offset */
_ASSEM_JUMPTABLE = 15
const /* Jumptable (switch -exact) */
_ASSEM_LABEL = 16
const /* The assembly directive that defines a
 * label */
_ASSEM_LINDEX_MULTI = 17
const /* 4-byte operand count, must be strictly
 * positive, consumes N, produces 1 */
_ASSEM_LIST = 18
const /* 4-byte operand count, must be nonnegative,
 * consumses N, produces 1 */
_ASSEM_LSET_FLAT = 19
const /* 4-byte operand count, must be >= 3,
 * consumes N, produces 1 */
_ASSEM_LVT = 20
const /* One operand that references a local
 * variable */
_ASSEM_LVT1 = 21
const /* One 1-byte operand that references a local
 * variable */
_ASSEM_LVT1_SINT1 = 22
const /* One 1-byte operand that references a local
 * variable, one signed-integer 1-byte
 * operand */
_ASSEM_LVT4 = 23
const /* One 4-byte operand that references a local
 * variable */
_ASSEM_OVER = 24
const /* OVER: 4-byte operand count, consumes N+1,
 * produces N+2 */
_ASSEM_PUSH = 25
const /* one literal operand */
_ASSEM_REGEXP = 26
const /* One Boolean operand, but weird mapping to
 * call flags */
_ASSEM_REVERSE = 27
const /* REVERSE: 4-byte operand count, consumes N,
 * produces N */
_ASSEM_SINT1 = 28
const /* One 1-byte signed-integer operand
 * (INCR_STK_IMM) */
_ASSEM_SINT4_LVT4 = 29

