	var _ /* literal at bp+8 */ uintptr
	var _ /* stop at bp+24 */ uintptr
	_, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _, _ = _needed, _objPtr, _objPtr1, _objPtr2, _objPtr3, _objPtr4, allocated, code, complete, errCode, incomplete, incompletePtr, insertMark, lastParsed, limit, mark, msg, nestedPtr, newPtr, newPtr1, nodePtr, nodes, nodesAvailable, nodesUsed, oldPtr, post, precedence, scanned, size, subErrCode, tokenPtr, wordIndex, v1, v10, v11, v12, v13, v14, v15, v16, v17, v18, v19, v2, v20, v21, v22, v23, v24, v25, v26, v27, v28, v29, v30, v31, v32, v33, v34, v35, v36, v37, v4, v5, v6, v7, v8, v9
