/*
 *----------------------------------------------------------------------
 *
 * TclpUtfNcmp2 --
 *
 *	Compare at most numBytes bytes of utf-8 strings cs and ct. Both cs and
 *	ct are assumed to be at least numBytes bytes long.
 *
 * Results:
 *	Return <0 if cs < ct, 0 if cs == ct, or >0 if cs > ct.
 *
 * Side effects:
 *	None.
 *
 *----------------------------------------------------------------------
 */

func x_TclpUtfNcmp2(tls *libc.TLS, cs uintptr, ct uintptr, numBytes uint32) (r int32) {
	/* Number of *bytes* to compare. */
	var c1, c2 uint8
	var result, v2, v3 int32
	_, _, _, _, _ = c1, c2, result, v2, v3
	/*
	 * We can't simply call 'memcmp(cs, ct, numBytes);' because we need to
	 * check for Tcl's \xC0\x80 non-utf-8 null encoding. Otherwise utf-8 lexes
	 * fine in the strcmp manner.
	 */
	result = 0
	for {
		if !(numBytes != uint32(0)) {
			break
		}
		if int32(*(*int8)(unsafe.Pointer(cs))) != int32(*(*int8)(unsafe.Pointer(ct))) {
			result = int32(uint8(*(*int8)(unsafe.Pointer(cs)))) - int32(uint8(*(*int8)(unsafe.Pointer(ct))))
			break
		}
		goto _1
	_1:
		;
		numBytes--
		cs++
		ct++
	}
	if numBytes != 0 && (int32(uint8(*(*int8)(unsafe.Pointer(cs)))) == int32(0xC0) || int32(uint8(*(*int8)(unsafe.Pointer(ct)))) == int32(0xC0)) {
		if int32(uint8(*(*int8)(unsafe.Pointer(cs)))) == int32(0xC0) && int32(uint8(*(*int8)(unsafe.Pointer(cs + 1)))) == int32(0x80) {
			v2 = 0
		} else {
			v2 = int32(uint8(*(*int8)(unsafe.Pointer(cs))))
		}
		c1 = uint8(v2)
		if int32(uint8(*(*int8)(unsafe.Pointer(ct)))) == int32(0xC0) && int32(uint8(*(*int8)(unsafe.Pointer(ct + 1)))) == int32(0x80) {
			v3 = 0
		} else {
			v3 = int32(uint8(*(*int8)(unsafe.Pointer(ct))))
		}
		c2 = uint8(v3)
		result = int32(c1) - int32(c2)
	}
	return result
}

