		*(*int8)(unsafe.Pointer(buf + 2)) = int8((ch | libc.Int32FromInt32(0x80)) & libc.Int32FromInt32(0xBF))
		*(*int8)(unsafe.Pointer(buf + 1)) = int8((ch>>libc.Int32FromInt32(6) | libc.Int32FromInt32(0x80)) & libc.Int32FromInt32(0xBF))
