		(*(*TTcl_Time)(unsafe.Pointer(bp + 8))).Fsec = desired.Fsec - (*(*TTcl_Time)(unsafe.Pointer(bp))).Fsec
		(*(*TTcl_Time)(unsafe.Pointer(bp + 8))).Fusec = desired.Fusec - (*(*TTcl_Time)(unsafe.Pointer(bp))).Fusec
